  "kb.emptyBidsD": { lv: "Kad būsi solījis, šeit redzēsi visus savus lotus: kur vadi, kur tevi pārsolīja un ko esi uzvarējis.", ru: "Когда сделаешь ставку, здесь будут все твои лоты: где ведёшь, где перебили и что выиграл.", en: "Once you bid, all your lots appear here: where you lead, where you were outbid and what you won.", et: "Kui pakud, näed siin kõiki oma partiisid: kus juhid, kus üle pakuti ja mida võitsid.", lt: "Kai pasiūlysi, čia matysi visus savo lotus: kur pirmauji, kur perlicitavo ir ką laimėjai." },
  "kb.emptyOverT": { lv: "Pašlaik nekur nesoli", ru: "Сейчас нигде не торгуешься", en: "You are not bidding anywhere", et: "Praegu sa ei paku kuskil", lt: "Šiuo metu niekur nesiūlai" },
  "kb.emptyOverD": { lv: "Izvēlies lotu katalogā vai pieslēdzies tiešraidei — tur redzēsi, kas beidzas tuvākajā stundā.", ru: "Выбери лот в каталоге или подключись к эфиру — там видно, что кончается в ближайший час.", en: "Pick a lot in the catalogue or join the live room to see what ends within the hour.", et: "Vali kataloogist partii või liitu otseülekandega — seal näed, mis lõpeb tunni jooksul.", lt: "Išsirink lotą kataloge arba prisijunk prie tiesioginės — ten matysi, kas baigiasi per valandą." },
  "kb.nothingWaits": { lv: "Nekas negaida darbību.", ru: "Ничего не ждёт действий.", en: "Nothing needs your attention.", et: "Miski ei oota tegutsemist.", lt: "Niekas nelaukia veiksmų." },
  "kb.consoleIntro": { lv: "Soli līdz četriem lotiem vienlaikus — noder, kad divi beidzas vienā laikā. Uzliec maksimumu katram, un mēs solīsim tavā vietā līdz šai summai.", ru: "Торгуйся до четырёх лотов сразу — выручает, когда два кончаются одновременно. Поставь максимум каждому, и мы будем ставить за тебя до этой суммы.", en: "Bid on up to four lots at once — handy when two end at the same time. Set a maximum for each and we bid for you up to that amount.", et: "Paku kuni neljale partiile korraga. Määra igale maksimum ja pakume sinu eest kuni selle summani.", lt: "Siūlyk iki keturių lotų vienu metu. Nustatyk kiekvienam maksimumą ir siūlysime už tave iki šios sumos." },
  "kb.consoleEmptyT": { lv: "Konsole ir tukša", ru: "Консоль пуста", en: "The console is empty", et: "Konsool on tühi", lt: "Konsolė tuščia" },
  "kb.consoleEmptyD": { lv: "Pievieno lotus no vēlmju saraksta vai no tiem, par kuriem jau soli — un soli tos visus no vienas vietas.", ru: "Добавь лоты из избранного или из тех, где уже торгуешься, — и веди их все из одного места.", en: "Add lots from your watchlist or ones you already bid on — and run them all from one place.", et: "Lisa partiid jälgimisnimekirjast või juba pakutud — ja juhi neid ühest kohast.", lt: "Pridėk lotus iš norų sąrašo arba tuos, dėl kurių jau siūlai — ir valdyk juos iš vienos vietos." },
  "kb.clearAll": { lv: "Notīrīt visu", ru: "Очистить всё", en: "Clear all", et: "Tühjenda kõik", lt: "Išvalyti viską" },
