  "kb.historySummary": { lv: "{bidders} solītāji · {bids} solījumi · sākuma cena {start}", ru: "{bidders} участников · {bids} ставок · стартовая цена {start}", en: "{bidders} bidders · {bids} bids · starting price {start}", et: "{bidders} pakkujat · {bids} pakkumist · alghind {start}", lt: "{bidders} dalyviai · {bids} pasiūlymai · pradinė kaina {start}" },
  "kb.historyAnon": { lv: "Vārdus nerādām — katrs solītājs redzams kā segvārds", ru: "Имён не показываем — каждый участник виден по никнейму", en: "No names shown — every bidder appears as a nickname", et: "Nimesid ei näita — iga pakkuja on hüüdnimega", lt: "Vardų nerodome — kiekvienas dalyvis matomas slapyvardžiu" },
  "kb.auto": { lv: "Auto", ru: "Авто", en: "Auto", et: "Auto", lt: "Auto" },
  "kb.leads": { lv: "Vada", ru: "Ведёт", en: "Leads", et: "Juhib", lt: "Pirmauja" },
  "kb.whyAuto": { lv: "Kāpēc daži solījumi seko cits citam sekundē: tā strādā automātiskais solījums. Tu norādi maksimumu, sistēma paaugstina soli tikai tik, cik vajag, lai vadītu. Tavs maksimums citiem nav redzams.", ru: "Почему некоторые ставки идут друг за другом в одну секунду: так работают автоставки. Ты задаёшь максимум, система поднимает шаг ровно настолько, чтобы вести. Твой максимум никому не виден.", en: "Why some bids follow within a second: that is the auto-bidder. You set a maximum and the system raises only as much as needed to lead. Your maximum is never shown.", et: "Miks mõned pakkumised järgnevad sekundiga: nii töötab automaatpakkuja. Sina määrad maksimumi, süsteem tõstab vaid vajaliku võrra. Sinu maksimumi ei näidata.", lt: "Kodėl kai kurie pasiūlymai seka per sekundę: taip veikia automatinis siūlytojas. Nustatai maksimumą, sistema kelia tik tiek, kiek reikia. Tavo maksimumas nerodomas." },
  "kb.changeMax": { lv: "Mainīt maksimumu", ru: "Изменить максимум", en: "Change maximum", et: "Muuda maksimumi", lt: "Keisti maksimumą" },
  "kb.toLot": { lv: "Uz lota lapu", ru: "На страницу лота", en: "To the lot page", et: "Partii lehele", lt: "Į loto puslapį" },
