  "kb.emptyPurchD": { lv: "Uzvarētie un nopirktie loti parādīsies šeit kopā ar rēķinu un saņemšanas informāciju.", ru: "Выигранные и купленные лоты появятся здесь вместе со счётом и информацией о получении.", en: "Won and bought lots appear here with the invoice and pickup details.", et: "Võidetud ja ostetud partiid ilmuvad siia koos arve ja kättesaamise infoga.", lt: "Laimėti ir nupirkti lotai atsiras čia kartu su sąskaita ir atsiėmimo informacija." },
  "kb.wishesSub": { lv: "{n} saglabāti loti. Brīdinām pirms beigām.", ru: "Сохранено лотов: {n}. Предупредим перед концом.", en: "{n} saved lots. We warn you before the end.", et: "{n} salvestatud partiid. Hoiatame enne lõppu.", lt: "{n} išsaugoti lotai. Perspėsime prieš pabaigą." },
  "kb.emptyWishT": { lv: "Vēlmju saraksts ir tukšs", ru: "Список избранного пуст", en: "Your watchlist is empty", et: "Jälgimisnimekiri on tühi", lt: "Norų sąrašas tuščias" },
  "kb.emptyWishD": { lv: "Nospied sirsniņu uz jebkura lota — un tas parādīsies šeit. Brīdināsim pirms beigām.", ru: "Нажми сердечко на любом лоте — и он появится здесь. Предупредим перед концом.", en: "Tap the heart on any lot — it shows up here. We warn you before the end.", et: "Vajuta südant ükskõik millisel partiil — see ilmub siia.", lt: "Paspausk širdelę ant bet kurio loto — jis atsiras čia." },
