  "kb.alertsSub": { lv: "Kas notiek ar lotiem, kurus tu seko.", ru: "Что происходит с лотами, за которыми следишь.", en: "What is happening with the lots you follow.", et: "Mis toimub partiidega, mida jälgid.", lt: "Kas vyksta su lotais, kuriuos seki." },
  "kb.emptyAlertsT": { lv: "Brīdinājumu vēl nav", ru: "Уведомлений пока нет", en: "No alerts yet", et: "Teavitusi veel pole", lt: "Pranešimų dar nėra" },
