  "kb.deleteLaw": { lv: "Rēķinus un darījumu datus grāmatvedība glabā 5 gadus, kā to prasa likums — tie netiek dzēsti, bet vairs nav saistīti ar publisko profilu.", ru: "Счета и данные сделок бухгалтерия хранит 5 лет, как требует закон, — они не удаляются, но больше не связаны с публичным профилем.", en: "Invoices and transaction data are kept for 5 years as the law requires — they are not deleted but are no longer tied to the public profile.", et: "Arveid ja tehinguandmeid hoitakse seaduse järgi 5 aastat.", lt: "Sąskaitos ir sandorių duomenys saugomi 5 metus, kaip reikalauja įstatymas." },
  "kb.deleteVia": { lv: "Dzēšanas pieprasījumu izskata atbalsts — uzraksti mums, atbildēsim vienas darba dienas laikā.", ru: "Запрос на удаление рассматривает поддержка — напиши нам, ответим в течение рабочего дня.", en: "Deletion requests are handled by support — write to us and we reply within one business day.", et: "Kustutamistaotlusi menetleb tugi — kirjuta meile.", lt: "Trynimo prašymus nagrinėja pagalba — parašyk mums." },
