  "sa.error": { lv: "Neizdevās ienākt caur sociālo tīklu — mēģini vēlreiz vai izmanto e-pastu", ru: "Не получилось войти через соцсеть — попробуйте ещё раз или войдите по почте", en: "Social sign-in failed — try again or use your email", et: "Sotsiaalvõrgu kaudu sisselogimine ebaõnnestus — proovi uuesti või kasuta e-posti", lt: "Nepavyko prisijungti per socialinį tinklą — bandykite dar kartą arba naudokite el. paštą" },
  "sa.tgTitle": { lv: "Ienākšana ar Telegram", ru: "Вход через Telegram", en: "Sign in with Telegram", et: "Telegramiga sisselogimine", lt: "Prisijungimas per Telegram" },
  "sa.tgSub": { lv: "Bez parolēm — ieeju apstiprināsi savā Telegram lietotnē.", ru: "Без паролей — вход подтверждается в вашем приложении Telegram.", en: "No passwords — you confirm the sign-in in your Telegram app.", et: "Ilma paroolideta — kinnitad sisselogimise oma Telegrami äpis.", lt: "Be slaptažodžių — prisijungimą patvirtinsite savo Telegram programėlėje." },
  "sa.tgStep1": { lv: "Nospied zilo Telegram pogu augstāk.", ru: "Нажмите синюю кнопку Telegram выше.", en: "Tap the blue Telegram button above.", et: "Vajuta ülal sinist Telegrami nuppu.", lt: "Paspauskite mėlyną Telegram mygtuką viršuje." },
  "sa.tgStep2": { lv: "Telegram lietotnē apstiprini ieeju vietnē izsoli.lv.", ru: "В приложении Telegram подтвердите вход на izsoli.lv.", en: "Confirm the izsoli.lv sign-in in the Telegram app.", et: "Kinnita Telegrami äpis izsoli.lv sisselogimine.", lt: "Telegram programėlėje patvirtinkite prisijungimą prie izsoli.lv." },
  "sa.tgStep3": { lv: "Atgriezīsies šeit jau ienācis — pēc tam pievieno e-pastu profilā.", ru: "Вернётесь сюда уже вошедшим — потом добавьте почту в профиле.", en: "You return here signed in — then add an email in your profile.", et: "Naased siia sisselogituna — seejärel lisa profiilis e-post.", lt: "Grįšite čia jau prisijungę — tada profilyje pridėkite el. paštą." },
